/* 📐 the left HUD column (coins, bus/score pills, way-finder, map, job, notepad, designer card) always fits the screen: when it runs off the
   bottom (a phone held sideways, several pills at once) or onto the joystick, only as many steps as needed, in this order: in a cut-scene the
   hidden boxes give their space, the notepad moves beside the map, the task list folds, the designer card drops its picture and then sits
   beside the map, the notepad hides, the map hides */
const LFC=['lfCut','lfPad','lfTasks','lfDc','lfDcS','lfNoPad','lfNoMap'];
function leftFit(){const L=$('left'),pad=$('pad'),dc=$('dcard'),mm=$('mmBtn');if(!L||!pad||!dc||!mm)return;
  L.classList.remove(...LFC);pad.style.left=pad.style.top=dc.style.left=dc.style.top='';if($('hud').hidden)return;
  const bad=()=>{const H=innerHeight-8,j=boxOf($('joy'));for(const el of[...L.children].flatMap(e=>e.id==='job'?[...e.children]:[e])){const r=boxOf(el);if(!r)continue;if(r.bottom>H)return true;   /* off the bottom, or on the joystick */
      if(j&&r.left<j.right&&r.right>j.left&&r.bottom>j.top-6&&r.top<j.bottom)return true;}return false;},
    side=(el,k)=>{if(!boxOf(mm)||!boxOf(el))return;const x=mm.offsetLeft+mm.offsetWidth+8;if(L.offsetLeft+x+el.offsetWidth>innerWidth*.5)return;   /* a phone held upright: not beside the map, that is the middle of the view (the ball, the kids) */
      L.classList.add(k);el.style.left=x+'px';el.style.top=mm.offsetTop+'px';},
    steps=[()=>{if(document.body.classList.contains('cut'))L.classList.add('lfCut');},()=>side(pad,'lfPad'),()=>{if(boxOf($('tasks')))L.classList.add('lfTasks');},
      ()=>{if(boxOf(dc))L.classList.add('lfDc');},()=>side(dc,'lfDcS'),()=>{if(boxOf(pad))L.classList.add('lfNoPad');},
      ()=>{if(!boxOf(mm))return;L.classList.add('lfNoMap');L.classList.remove('lfPad','lfDcS');pad.style.left=pad.style.top=dc.style.left=dc.style.top='';}];
  for(const st of steps){if(!bad())break;st();}updPlace();}
new MutationObserver(()=>leftFit()).observe($('left'),{childList:true,subtree:true,attributes:true,attributeFilter:['hidden']});   /* a pill or box comes or goes */
addEventListener('resize',()=>setTimeout(leftFit,60));
{const st=document.createElement('style');st.textContent='#left.lfPad #pad,#left.lfDcS #dcard{position:absolute;margin:0}#left.lfDc #dcard .dci{display:none}#left.lfNoPad #pad,#left.lfNoMap #mmBtn,#left.lfTasks #tasks ul,.cut #left.lfCut #nav,.cut #left.lfCut #job{display:none}'
  /* 🧹 glitch fixes, pass 2: on a phone held upright the column is narrow (it shares the top row with the round buttons), so the pink arrow bar
     became a tall column of single words and the score pill ran out of its box. The bars below the clock may now be as wide as their words */
  +'@media (max-width:600px){#left>#nav,#left>#busTip,#left>#fbHud,#left>#tnHud{width:max-content;max-width:calc(100vw - 24px - env(safe-area-inset-left,0px) - env(safe-area-inset-right,0px))}}#navX{flex:0 0 auto}#card.bustab.more::after{margin:-44px auto 0}';document.head.appendChild(st);}
