addEventListener('keydown',e=>{if(!document.body.classList.contains('bookopen'))return;if(e.key==='ArrowRight')bookGo(1);else if(e.key==='ArrowLeft')bookGo(-1);else if(e.key==='Escape')bookClose();else return;
  e.preventDefault();e.stopImmediatePropagation();},true);   /* the book's keys never reach the game */
