  bake(g);const sg=signPlane('💡 Ideas Board',2.05,.3,'#fff7fb','#3d2c5e');sg.position.set(0,2.23,.066);g.add(sg);   /* 1.6 cm in front of the header board (run 4, job 5: it was 2 mm) */g.visible=false;L.g.add(g);BD.g=g;
  const c=Math.cos(ry),s=Math.sin(ry);for(const k of[-.85,0,.85])BD.cols.push({cx:X+c*k,cz:Z-s*k,cr:.32});   /* only solid while the board is shown */
